ALTER TABLE "notification_attempts" ADD CONSTRAINT "notification_attempts_email" CHECK (("notification_attempts"."status" NOT IN ('SENT','FAILED','EXPIRED','SUPPRESSED') OR "notification_attempts"."recipient_email" IS NULL) AND ("notification_attempts"."status" <> 'PENDING' OR "notification_attempts"."channel" <> 'email' OR "notification_attempts"."recipient_email" IS NOT NULL) AND ("notification_attempts"."channel" = 'email' OR "notification_attempts"."recipient_email" IS NULL) AND ("notification_attempts"."recipient_email" IS NULL OR (length("notification_attempts"."recipient_email") <= 254 AND "notification_attempts"."recipient_email" ~ '^[^[:space:]@]+@[a-z0-9.-]+[.][a-z]{2,63}$')));--> statement-breakpoint
ALTER TABLE "notification_attempts" ADD CONSTRAINT "notification_attempts_phone" CHECK (("notification_attempts"."status" NOT IN ('SENT','FAILED','EXPIRED','SUPPRESSED') OR "notification_attempts"."recipient_phone" IS NULL) AND ("notification_attempts"."status" <> 'PENDING' OR "notification_attempts"."channel" <> 'whatsapp' OR "notification_attempts"."recipient_phone" IS NOT NULL) AND ("notification_attempts"."recipient_phone" IS NULL OR "notification_attempts"."recipient_phone" ~ '^[+][1-9][0-9]{7,14}$') AND ("notification_attempts"."channel" = 'whatsapp' OR "notification_attempts"."recipient_phone" IS NULL));--> statement-breakpoint
ALTER TABLE "notification_attempts" ADD CONSTRAINT "notification_attempts_hash" CHECK (octet_length("notification_attempts"."recipient_hash") = 32 AND (("notification_attempts"."channel" = 'whatsapp' AND "notification_attempts"."phone_last3" IS NOT NULL AND "notification_attempts"."phone_last3" ~ '^[0-9]{3}$') OR ("notification_attempts"."channel" = 'email' AND "notification_attempts"."phone_last3" IS NULL)));--> statement-breakpoint
